# test-conflict-detection.ps1 -- Verify FUSE conflict detection and re-sync behavior (Windows).
#
# Usage: .\test-conflict-detection.ps1 [-MountPoint <path>] [-ApiUrl <url>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#
# Environment:
#   TEST_SECRET   Shared secret for test-login (default: e2e-test-secret-ci-only)
#
# These tests verify that when the server-side IPNS sequence number is bumped
# (simulating another device publishing), the desktop detects the 409 conflict,
# re-syncs, and retries -- resulting in all files/directories being accessible.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000"
)

$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$ErrorActionPreference = "Continue"

$TestEmail = "dev-key@cipherbox.local"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== Conflict Detection Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host ""

# ---- Setup: Authenticate via test-login ----
Write-Host "--- Setup: Authenticate via test-login ---"
$Body = @{
    email  = $TestEmail
    secret = $TestSecret
} | ConvertTo-Json

$AccessToken = $null
try {
    $AuthResponse = Invoke-RestMethod -Uri "$ApiUrl/auth/test-login" `
        -Method Post `
        -ContentType "application/json" `
        -Body $Body
    $AccessToken = $AuthResponse.accessToken
} catch {
    Write-Host "FATAL: Authentication failed ($_)"
}

if (-not $AccessToken) {
    Write-Host "FATAL: Cannot proceed without authentication."
    Write-Host ""
    Write-Host "=== Conflict Detection Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "=================================="
    exit 1
}
Write-Host "  Authenticated successfully"

$Headers = @{ Authorization = "Bearer $AccessToken" }

# ---- Setup: Get root IPNS name from vault ----
Write-Host "--- Setup: Get root IPNS name from vault ---"
$RootIpns = $null
try {
    $VaultResponse = Invoke-RestMethod -Uri "$ApiUrl/vault" -Headers $Headers
    $RootIpns = $VaultResponse.rootIpnsName
} catch {
    Write-Host "FATAL: Failed to retrieve vault ($_)"
}

if (-not $RootIpns) {
    Write-Host "FATAL: No rootIpnsName found in vault -- cannot test conflict detection without a published vault."
    Write-Host "       Ensure the desktop app has made at least one FUSE write before running this test."
    Write-Host ""
    Write-Host "=== Conflict Detection Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "=================================="
    exit 1
}
Write-Host "  Root IPNS: $RootIpns"
Write-Host ""

# ---- Helper: Invoke-BumpServerSequence ----
# Bumps the server-side sequence number for a given IPNS name by publishing
# without expectedSequenceNumber (backward-compatible unconditional publish).
# This simulates another device publishing to the same folder.
function Invoke-BumpServerSequence {
    param([string]$IpnsName)

    # 1. Resolve current CID for this IPNS name (for the metadataCid field)
    $CurrentCid = $null
    try {
        $ResolveResp = Invoke-RestMethod -Uri "$ApiUrl/ipns/resolve?ipnsName=$IpnsName" -Headers $Headers
        $CurrentCid = if ($ResolveResp.cid) { $ResolveResp.cid } else { $ResolveResp.value }
    } catch {
        Write-Host "  WARNING: Could not resolve CID for $IpnsName"
    }

    if (-not $CurrentCid) {
        Write-Host "  WARNING: Using placeholder CID for $IpnsName"
        $CurrentCid = "bafybeigdyrzt5sfp7udm7hu76uh7y26nf3efuylqabf3oclgtqy55fbzdi"
    }

    # 2. Publish with a dummy record and no expectedSequenceNumber.
    #    This unconditionally increments the server-side sequence number,
    #    making the desktop's cached sequence stale.
    $DummyRecord = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes("dummy-conflict-test-record"))

    $PublishBody = @{
        ipnsName    = $IpnsName
        record      = $DummyRecord
        metadataCid = $CurrentCid
    } | ConvertTo-Json

    try {
        $PublishResp = Invoke-RestMethod -Uri "$ApiUrl/ipns/publish" `
            -Method Post `
            -Headers $Headers `
            -ContentType "application/json" `
            -Body $PublishBody
        if ($PublishResp.success) {
            Write-Host "  Server sequence bumped to $($PublishResp.sequenceNumber) for $IpnsName"
        } else {
            throw "Publish response did not indicate success for $IpnsName"
        }
    } catch {
        throw "Failed to bump server sequence for ${IpnsName}: $_"
    }
}

# ---- Test 1: Write file via FUSE, bump server seq, write another file -> both readable ----
Write-Host "--- Test 1: Write file, bump server sequence, write another file -> both readable ---"

# Step 1: Write first file and wait for FUSE debounce + publish
try {
    Set-Content -Path "$MountPoint\conflict-test-1.txt" -Value "file-before-bump" -NoNewline -ErrorAction Stop
    Write-Host "  Wrote conflict-test-1.txt, waiting 8s for FUSE publish..."
    Start-Sleep -Seconds 8
} catch {
    Write-Host "  WARNING: Failed to write conflict-test-1.txt ($_)"
}

# Step 2: Bump server sequence to make desktop's local sequence stale
Write-Host "  Bumping server sequence..."
Invoke-BumpServerSequence -IpnsName $RootIpns

# Step 3: Write second file -- the FUSE publish will get a 409, re-sync, and retry
try {
    Set-Content -Path "$MountPoint\conflict-test-2.txt" -Value "file-after-bump" -NoNewline -ErrorAction Stop
    Write-Host "  Wrote conflict-test-2.txt, waiting 15s for conflict resolution + retry..."
    Start-Sleep -Seconds 15
} catch {
    Write-Host "  WARNING: Failed to write conflict-test-2.txt ($_)"
}

# Step 4: Verify both files are readable
$Content1 = $null
$Content2 = $null
try { $Content1 = (Get-Content -Path "$MountPoint\conflict-test-1.txt" -Raw -ErrorAction Stop).Trim() } catch {}
try { $Content2 = (Get-Content -Path "$MountPoint\conflict-test-2.txt" -Raw -ErrorAction Stop).Trim() } catch {}

if ($Content1 -eq "file-before-bump" -and $Content2 -eq "file-after-bump") {
    Test-Pass "Write file conflict: both files readable after re-sync and retry"
} elseif ($Content1 -ne "file-before-bump") {
    Test-Fail "Write file conflict: conflict-test-1.txt has unexpected content (got: '$Content1')"
} else {
    Test-Fail "Write file conflict: conflict-test-2.txt has unexpected content (got: '$Content2')"
}

# ---- Test 2: Create directory via FUSE, bump server seq, create file in dir -> both accessible ----
Write-Host "--- Test 2: Create directory, bump server sequence, create file in dir -> both accessible ---"

# Step 1: Create directory and wait for FUSE publish
try {
    New-Item -ItemType Directory -Path "$MountPoint\conflict-dir" -Force -ErrorAction Stop | Out-Null
    Write-Host "  Created conflict-dir, waiting 8s for FUSE publish..."
    Start-Sleep -Seconds 8
} catch {
    Write-Host "  WARNING: Failed to create conflict-dir ($_)"
}

# Step 2: Bump server sequence
Write-Host "  Bumping server sequence..."
Invoke-BumpServerSequence -IpnsName $RootIpns

# Step 3: Write file in directory -- the mkdir publish will hit 409, re-sync, retry
try {
    Set-Content -Path "$MountPoint\conflict-dir\nested.txt" -Value "nested-conflict-file" -NoNewline -ErrorAction Stop
    Write-Host "  Writing conflict-dir\nested.txt, waiting 15s for conflict resolution + retry..."
    Start-Sleep -Seconds 15
} catch {
    Write-Host "  WARNING: Failed to write conflict-dir\nested.txt ($_)"
}

# Step 4: Verify directory exists and file is readable
$DirExists = Test-Path "$MountPoint\conflict-dir" -PathType Container
$Nested = $null
try { $Nested = (Get-Content -Path "$MountPoint\conflict-dir\nested.txt" -Raw -ErrorAction Stop).Trim() } catch {}

if ($DirExists -and $Nested -eq "nested-conflict-file") {
    Test-Pass "Directory conflict: dir exists and nested file readable after re-sync and retry"
} elseif (-not $DirExists) {
    Test-Fail "Directory conflict: conflict-dir does not exist after re-sync"
} else {
    Test-Fail "Directory conflict: nested.txt has unexpected content (got: '$Nested')"
}

# ---- Cleanup ----
# Wrap in try/catch: on WinFSP mounts, Remove-Item can throw terminating
# .NET exceptions ("The system cannot find the file specified") that
# -ErrorAction SilentlyContinue does not suppress.
Write-Host "--- Cleanup ---"
try { Remove-Item -Path "$MountPoint\conflict-test-1.txt" -Force -ErrorAction SilentlyContinue } catch {}
try { Remove-Item -Path "$MountPoint\conflict-test-2.txt" -Force -ErrorAction SilentlyContinue } catch {}
try { Remove-Item -Path "$MountPoint\conflict-dir" -Recurse -Force -ErrorAction SilentlyContinue } catch {}
Start-Sleep -Seconds 3

# ---- Summary ----
Write-Host ""
Write-Host "=== Conflict Detection Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "=================================="

exit $Fail

# test-round-trip.ps1 -- Verify desktop FUSE writes are visible via the API (Windows).
#
# Usage: .\test-round-trip.ps1 [-MountPoint <path>] [-ApiUrl <url>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#
# Environment:
#   TEST_SECRET   Shared secret for test-login (default: e2e-test-secret-ci-only)
#
# The server is zero-knowledge -- it cannot decrypt file contents.
# These tests prove the pipeline: FUSE write -> encrypt -> IPFS upload -> IPNS publish -> API visibility.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000"
)

$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$ErrorActionPreference = "Continue"

# Use the same email as the dev-key auth flow so we query the same user's vault
$TestEmail = "dev-key@cipherbox.local"
$RepoRoot = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot "..\..\.."))
$TestFile = "rt-test-$PID-$(Get-Random).txt"
$TestContent = "API-visible content"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

function Ensure-VerifierRuntime {
    $sdkCoreDist = Join-Path $RepoRoot "packages/sdk-core/dist/index.mjs"
    $apiClientDist = Join-Path $RepoRoot "packages/api-client/dist/index.mjs"

    if ((Test-Path $sdkCoreDist) -and (Test-Path $apiClientDist)) {
        return
    }

    & pnpm --dir $RepoRoot --filter @cipherbox/crypto build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/crypto" }

    & pnpm --dir $RepoRoot --filter @cipherbox/core build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/core" }

    & pnpm --dir $RepoRoot --filter @cipherbox/api-client build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/api-client" }

    & pnpm --dir $RepoRoot --filter @cipherbox/sdk-core build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/sdk-core" }
}

Write-Host "=== API Round-Trip Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host "Test file:   $TestFile"
Write-Host ""

Ensure-VerifierRuntime

function Invoke-FilePointerVerifier {
    $verifierPath = Join-Path $RepoRoot "packages/sdk-core/scripts/verify-filepointer.mjs"
    $env:TEST_SECRET = $TestSecret
    $output = & node $verifierPath `
        --api-url $ApiUrl `
        --email $TestEmail `
        --file-name $TestFile `
        --expected-content $TestContent 2>&1 | Out-String

    return @($LASTEXITCODE, $output.Trim())
}

# ---- Test 1: Authenticate via test-login ----
Write-Host "--- Test 1: Authenticate via test-login ---"
$Body = @{
    email  = $TestEmail
    secret = $TestSecret
} | ConvertTo-Json

try {
    $AuthResponse = Invoke-RestMethod -Uri "$ApiUrl/auth/test-login" `
        -Method Post `
        -ContentType "application/json" `
        -Body $Body

    $AccessToken = $AuthResponse.accessToken
    if ($AccessToken) {
        Test-Pass "Authenticate via test-login"
    } else {
        Test-Fail "Authenticate via test-login (no accessToken in response)"
        Write-Host "FATAL: Cannot proceed without authentication."
        Write-Host ""
        Write-Host "=== API Round-Trip Results ==="
        Write-Host "  Passed: $Pass"
        Write-Host "  Failed: $Fail"
        Write-Host "==============================="
        exit $Fail
    }
} catch {
    Test-Fail "Authenticate via test-login ($_)"
    Write-Host "FATAL: Cannot proceed without authentication."
    Write-Host ""
    Write-Host "=== API Round-Trip Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "==============================="
    exit $Fail
}

$Headers = @{ Authorization = "Bearer $AccessToken" }

# ---- Test 2: Desktop writes file, API verifies vault exists ----
Write-Host "--- Test 2: Verify vault has content after FUSE write ---"
$FuseWriteSucceeded = $false
try {
    Set-Content -Path "$MountPoint\$TestFile" -Value $TestContent -NoNewline -ErrorAction Stop
    if (-not (Test-Path "$MountPoint\$TestFile")) { throw "FUSE write did not materialize at mount path" }
    $FuseWriteSucceeded = $true
    # Force a directory listing to drain upload completions — without this,
    # the background upload finishes but the publish queue never flushes
    # because no FUSE callbacks trigger drain_upload_completions() in CI.
    Start-Sleep -Seconds 2
    Get-ChildItem -Path $MountPoint -ErrorAction SilentlyContinue | Out-Null
} catch {
    Test-Fail "FUSE write failed ($_)"
}
if ($FuseWriteSucceeded) {
    $RootIpns = $null
    for ($attempt = 1; $attempt -le 24 -and -not $RootIpns; $attempt++) {
        Start-Sleep -Seconds 5
        try {
            $VaultResponse = Invoke-RestMethod -Uri "$ApiUrl/vault" -Headers $Headers
            $RootIpns = $VaultResponse.rootIpnsName
        } catch {
            Write-Host "  Vault poll attempt $attempt failed: $_"
        }
    }
    if ($RootIpns) {
        Test-Pass "Vault has rootIpnsName after FUSE write ($RootIpns)"
    } else {
        Test-Fail "Vault has no rootIpnsName after 120s polling"
    }
} else {
    Test-Fail "Vault verification skipped (FUSE write failed)"
    $RootIpns = $null
}

# ---- Test 3: Verify FilePointer and per-file IPNS metadata resolve ----
Write-Host "--- Test 3: Verify FilePointer and per-file IPNS metadata ---"
$VerifySucceeded = $false
$VerifyOutput = ""
for ($attempt = 1; $attempt -le 24 -and -not $VerifySucceeded; $attempt++) {
    Start-Sleep -Seconds 5
    $verifyResult = Invoke-FilePointerVerifier
    $verifyExit = [int]$verifyResult[0]
    $VerifyOutput = [string]$verifyResult[1]
    if ($verifyExit -eq 0) {
        $VerifySucceeded = $true
    } else {
        Write-Host "  FilePointer verify attempt $attempt failed: $VerifyOutput"
    }
}

if ($VerifySucceeded) {
    Test-Pass "FilePointer exists and per-file IPNS metadata resolves"
    Write-Host "  $VerifyOutput"
} else {
    Test-Fail "FilePointer/per-file IPNS verification failed after 120s"
}

# ---- Test 4: Verify fresh client reload can still resolve file metadata ----
Write-Host "--- Test 4: Verify fresh client reload resolves file metadata ---"
Start-Sleep -Seconds 2
$reloadResult = Invoke-FilePointerVerifier
$reloadExit = [int]$reloadResult[0]
$reloadOutput = [string]$reloadResult[1]
if ($reloadExit -eq 0) {
    Test-Pass "Fresh client reload resolves file metadata and content"
    Write-Host "  $reloadOutput"
} else {
    Test-Fail "Fresh client reload failed to resolve file metadata ($reloadOutput)"
}

# ---- Test 5: Verify IPNS resolve returns data ----
Write-Host "--- Test 5: Verify IPNS resolve returns CID ---"
if ($RootIpns) {
    $ResolvedCid = $null
    for ($attempt = 1; $attempt -le 24 -and -not $ResolvedCid; $attempt++) {
        Start-Sleep -Seconds 2
        try {
            $IpnsResponse = Invoke-RestMethod -Uri "$ApiUrl/ipns/resolve?ipnsName=$RootIpns" -Headers $Headers
            $ResolvedCid = if ($IpnsResponse.cid) { $IpnsResponse.cid } else { $IpnsResponse.value }
        } catch {
            Write-Host "  IPNS resolve attempt $attempt failed: $_"
        }
    }
    if ($ResolvedCid) {
        Test-Pass "IPNS resolve returned CID ($ResolvedCid)"
    } else {
        Test-Fail "IPNS resolve did not return expected CID after 48s polling"
    }
} else {
    Test-Fail "IPNS resolve skipped (no rootIpnsName)"
}

# ---- Cleanup ----
Write-Host "--- Cleanup ---"
Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2

# ---- Summary ----
Write-Host ""
Write-Host "=== API Round-Trip Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "==============================="

exit $Fail

