4	
5	#[cfg(feature = "winfsp")]
6	pub mod implementation {
7	    use winfsp::filesystem::{DirInfo, DirMarker, FileInfo, WideNameInfo};
8	    use widestring::U16CString;
9	    use winfsp::FspError;
10	
11	    use crate::constants::CONTENT_DOWNLOAD_TIMEOUT;
12	    use crate::inode::InodeKind;
13	    use super::super::operations::implementation::{
14	        WinFspContext, WinFspFileContext,
15	        status_object_name_not_found,
16	        fill_file_info, fetch_and_decrypt_content_async,
17	        is_windows_special,
18	    };
19	
20	    /// read_directory handler
21	    pub fn handle_read_directory(
22	        ctx: &WinFspContext,
23	        context: &WinFspFileContext,
24	        marker: DirMarker,
25	        buffer: &mut [u8],
26	    ) -> Result<u32, FspError> {
27	        let mut fs = ctx.inner.lock().unwrap();
28	        let ino = context.ino;
29	
30	        fs.drain_refresh_completions();
31	        fs.drain_filepointer_completions();
32	        fs.drain_upload_completions();
33	
34	        let inode = fs
35	            .inodes
36	            .get(ino)
37	            .ok_or(status_object_name_not_found())?;
38	
39	        // Check if metadata is stale and fire background refresh
40	        let stale_info: Option<(String, zeroize::Zeroizing<Vec<u8>>)> =
41	            match &inode.kind {
42	                InodeKind::Root { ipns_name, .. } => {
43	                    ipns_name.as_ref().and_then(|name| {
44	                        if fs.metadata_cache.get(name).is_none() {
45	                            Some((name.clone(), fs.root_folder_key.clone()))
46	                        } else {
47	                            None
48	                        }
49	                    })
50	                }
51	                InodeKind::Folder { ipns_name, folder_key, .. } => {
52	                    if fs.metadata_cache.get(&ipns_name).is_none() {
53	                        Some((ipns_name.clone(), folder_key.clone()))
54	                    } else {
55	                        None
56	                    }
57	                }
58	                _ => None,
59	            };
60	
61	        if let Some((ipns_name, folder_key)) = stale_info {
62	            let api = fs.api.clone();
63	            let rt = fs.rt.clone();
64	            let tx = fs.refresh_tx.clone();
65	            let refresh_ino = ino;
66	            rt.spawn(async move {
67	                match cipherbox_api_client::ipns::resolve_ipns(&api, &ipns_name).await {
68	                    Ok(resolve_resp) => {
69	                        match cipherbox_api_client::ipfs::fetch_content(&api, &resolve_resp.cid).await {
70	                            Ok(encrypted_bytes) => {
71	                                match cipherbox_core::decrypt::decrypt_metadata_from_ipfs_public(
72	                                    &encrypted_bytes, &folder_key,
73	                                ) {
74	                                    Ok(metadata) => {
75	                                        let _ = tx.send(crate::PendingRefresh {
76	                                            ino: refresh_ino,
77	                                            ipns_name,
78	                                            metadata,
79	                                            cid: resolve_resp.cid,
80	                                        });
81	                                    }
82	                                    Err(e) => log::warn!("Refresh decrypt failed: {}", e),
83	                                }
84	                            }
85	                            Err(e) => log::warn!("Refresh fetch failed: {}", e),
86	                        }
87	                    }
88	                    Err(e) => log::warn!("Refresh resolve failed for {}: {}", ipns_name, e),
89	                }
90	            });
91	        }
92	
93	        let parent_ino = inode.parent_ino;
94	        let children = inode.children.clone().unwrap_or_default();
95	
96	        let mut entries: Vec<(U16CString, FileInfo)> = Vec::new();
97	
98	        if let Ok(name) = U16CString::from_str(".") {
99	            entries.push((name, fill_file_info(&inode.attr)));
100	        }
101	
102	        if let Some(parent) = fs.inodes.get(parent_ino) {
103	            if let Ok(name) = U16CString::from_str("..") {
104	                entries.push((name, fill_file_info(&parent.attr)));
105	            }
106	        }
107	
108	        for &child_ino in &children {
109	            if let Some(child) = fs.inodes.get(child_ino) {
110	                if is_windows_special(&child.name) {
111	                    continue;
112	                }
113	                if let Ok(name) = U16CString::from_str(&child.name) {
114	                    entries.push((name, fill_file_info(&child.attr)));
115	                }
116	            }
117	        }
118	
119	        let mut past_marker = marker.is_none();
120	        let mut bytes_written: u32 = 0;
121	
122	        for (entry_name, entry_info) in &entries {
123	            if !past_marker {
124	                let entry_str = entry_name.to_string_lossy();
125	                let is_match = if marker.is_current() {
126	                    entry_str == "."
127	                } else if marker.is_parent() {
128	                    entry_str == ".."
129	                } else if let Some(marker_cstr) = marker.inner_as_cstr() {
130	                    entry_str == marker_cstr.to_string_lossy()
131	                } else {
132	                    false
133	                };
